using TrelamiumIII.Core.Books.Layout;
using TrelamiumIII.Core.Books.Text;

namespace TrelamiumIII.Core.Books.Lore.Definitions;

/// <summary>Generated by the in-game authoring tool. Safe to edit by hand.</summary>
public sealed class AnniesDiaryBook : ModLoreBook
{
    public override string Key => "Misc.Diary";

    protected override void Build(BookBuilder book) 
    {
        book
            .Space(32f)
            .Heading("Title", rule: false, BlockStyle.Heading with { Scale = 0.9f, Align = TextAlign.Center })
            .Rule(span: 0.45f)
            .Space(12f)
            .Contents("ContentsHeader");

        Day(book, "Day1");
    }

    private static void Day(BookBuilder builder, string chapter)
    {
        builder
            .Chapter(chapter)

            .Prose($"{chapter}.Opening", BlockStyle.Body with { DropCap = true, Align = TextAlign.Left });
    }
}
